// keep the best score in a file: every new score is checked against it
define(fp, x29)
define(lr, x30)

define(n_r, x19)
define(i_r, x20)
define(score_r, x21)

define(AT_FDCWD, -100)
define(SYS_OPENAT, 56)
define(SYS_CLOSE, 57)
define(SYS_READ, 63)
define(SYS_WRITE, 64)

.data
path:       .string "best.dat"
fmt_count:  .string "%ld"
fmt_score:  .string "%ld"
fmt_first:  .string "first score: %ld\n"
fmt_new:    .string "new best: %ld (was %ld)\n"
fmt_keep:   .string "%ld does not beat %ld\n"
fmt_high:   .string "high score: %ld\n"
fmt_empty:  .string "no scores yet\n"

.bss
.align 3
count:      .skip 8
score_in:   .skip 8
saved:      .skip 8                         // the 8 bytes the file holds

.text

// TODO: write two subroutines that talk to the file through svc 0.
//
// load_best() -> x0 = 1 with the file's 8 bytes copied into saved, or
// x0 = 0 when the file cannot be opened (a negative result from openat)
//
// save_best(x0 = score): store the score in saved, open the file for
// writing (create it if missing, empty it if not), write the 8 bytes of
// saved, and close it
//
// A subroutine that keeps a value in x19 to x28 saves that register
// first and puts it back before ret.

        .balign 4
        .global main
main:
        stp     fp, lr, [sp, -16]!
        mov     fp, sp

        ldr     x0, =fmt_count
        ldr     x1, =count
        bl      scanf
        ldr     x9, =count
        ldr     n_r, [x9]

        // TODO: n times, read a score into score_in with fmt_score, then
        //   - no saved file yet: print fmt_first and save the score
        //   - the score beats the saved one: print fmt_new and save it
        //   - otherwise: print fmt_keep with the score and the saved one
        // At the end print fmt_high with the saved score, or fmt_empty
        // when there is still no file.

        mov     w0, 0
        ldp     fp, lr, [sp], 16
        ret
